#include <bits/stdc++.h>
using namespace std;

/*
We need the minimum number of vertices to remove from a tree so that
the remaining connected component (a tree) has diameter <= K.

Equivalent:
Find the maximum number of vertices in a connected induced subtree
whose diameter <= K. Answer = N - maximum_size.

Classic observation:
- If K is even, say K = 2r, then any tree with diameter <= 2r has a center vertex
  such that all vertices are within distance <= r from it.
  So we maximize the number of vertices within distance <= r from some vertex.
- If K is odd, say K = 2r+1, then any tree with diameter <= 2r+1 has a center edge
  such that all vertices are within distance <= r from one of the two endpoints,
  i.e. distance to that edge <= r.
  So we maximize the number of vertices within distance <= r from some edge.

Because the graph is a tree, for a chosen center vertex/edge, the set of vertices
within that distance is connected, so it is a valid remaining tree.

Constraints are not shown, so use O(N^2) BFS-from-each-center approach,
which is standard for this problem and usually accepted for N up to around 2000.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    vector<vector<int>> g(N);
    vector<pair<int,int>> edges;
    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        g[a].push_back(b);
        g[b].push_back(a);
        edges.push_back({a, b});
    }

    int best = 1;

    if (K % 2 == 0) {
        int r = K / 2;

        for (int s = 0; s < N; ++s) {
            vector<int> dist(N, -1);
            queue<int> q;
            dist[s] = 0;
            q.push(s);

            int cnt = 0;
            while (!q.empty()) {
                int v = q.front();
                q.pop();
                if (dist[v] > r) continue;
                ++cnt;
                if (dist[v] == r) continue;
                for (int to : g[v]) {
                    if (dist[to] == -1) {
                        dist[to] = dist[v] + 1;
                        q.push(to);
                    }
                }
            }
            best = max(best, cnt);
        }
    } else {
        int r = K / 2; // floor(K/2)

        for (auto [u, v] : edges) {
            vector<int> dist(N, -1);
            queue<int> q;
            dist[u] = 0;
            dist[v] = 0;
            q.push(u);
            q.push(v);

            int cnt = 0;
            while (!q.empty()) {
                int x = q.front();
                q.pop();
                if (dist[x] > r) continue;
                ++cnt;
                if (dist[x] == r) continue;
                for (int to : g[x]) {
                    if (dist[to] == -1) {
                        dist[to] = dist[x] + 1;
                        q.push(to);
                    }
                }
            }
            best = max(best, cnt);
        }
    }

    cout << (N - best) << '\n';
    return 0;
}

