#define MAXN 105

int n, k;
int adj[MAXN][MAXN];
int deg[MAXN];
int removed[MAXN];

int dist[MAXN][MAXN];

void bfs(int start) {
    int queue[MAXN], front = 0, back = 0;
    for (int i = 0; i < n; i++) dist[start][i] = -1;
    dist[start][start] = 0;
    queue[back++] = start;
    while (front < back) {
        int u = queue[front++];
        for (int v = 0; v < n; v++) {
            if (adj[u][v] && dist[start][v] == -1 && !removed[v]) {
                dist[start][v] = dist[start][u] + 1;
                queue[back++] = v;
            }
        }
    }
}

int main() {
    scanf("%d %d", &n, &k);
    memset(adj, 0, sizeof(adj));
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        adj[u][v] = adj[v][u] = 1;
    }

    int ans = n;
    // try all subsets of vertices to keep
    for (int mask = 0; mask < (1 << n); mask++) {
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            removed[i] = !(mask & (1 << i));
            if (!removed[i]) cnt++;
        }
        if (cnt <= ans) continue; // no need to check if smaller than current best

        // check if kept vertices form a connected subgraph with diameter <= k
        // find first kept vertex
        int start = -1;
        for (int i = 0; i < n; i++) {
            if (!removed[i]) { start = i; break; }
        }
        if (start == -1) continue;

        // BFS from start to count reachable kept vertices
        int queue[MAXN], front = 0, back = 0;
        int visited[MAXN] = {0};
        visited[start] = 1;
        queue[back++] = start;
        int reachable = 1;
        while (front < back) {
            int u = queue[front++];
            for (int v = 0; v < n; v++) {
                if (adj[u][v] && !removed[v] && !visited[v]) {
                    visited[v] = 1;
                    queue[back++] = v;
                    reachable++;
                }
            }
        }
        if (reachable != cnt) continue; // not connected

        // compute distances between all kept vertices
        for (int i = 0; i < n; i++) if (!removed[i]) bfs(i);
        int maxd = 0;
        for (int i = 0; i < n; i++) {
            if (removed[i]) continue;
            for (int j = i+1; j < n; j++) {
                if (removed[j]) continue;
                if (dist[i][j] > maxd) maxd = dist[i][j];
            }
        }
        if (maxd <= k) {
            if (cnt > n - ans) ans = n - cnt;
        }
    }

    printf("%d\n", ans);
    return 0;
}

