int main(void) {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;

    if (N <= 0) {
        printf("0\n");
        return 0;
    }

    int M = 2 * (N - 1);
    Edge *edges = (Edge *)malloc(sizeof(Edge) * (M > 0 ? M : 1));
    int *head = (int *)malloc(sizeof(int) * (N + 1));
    int *deg = (int *)calloc(N + 1, sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);

        edges[ecnt].to = v;
        edges[ecnt].next = head[u];
        head[u] = ecnt++;
        deg[u]++;

        edges[ecnt].to = u;
        edges[ecnt].next = head[v];
        head[v] = ecnt++;
        deg[v]++;
    }

    /*
      Key fact:
      A connected subgraph of a tree with diameter <= K is exactly a ball:
      - if K is even, centered at one vertex with radius K/2
      - if K is odd, centered at one edge with radius K/2 from both ends

      To maximize remaining vertices, try all possible centers and count how many
      vertices are within the allowed distance. Answer = N - maximum kept.
    */

    int *queue = (int *)malloc(sizeof(int) * (N + 5));
    int *dist = (int *)malloc(sizeof(int) * (N + 1));
    int *vis = (int *)malloc(sizeof(int) * (N + 1));
    int vis_id = 1;

    int bestKeep = 1;

    if (K % 2 == 0) {
        int R = K / 2;
        for (int s = 1; s <= N; s++) {
            int front = 0, back = 0;
            queue[back++] = s;
            vis[s] = vis_id;
            dist[s] = 0;
            int cnt = 0;

            while (front < back) {
                int u = queue[front++];
                cnt++;
                if (dist[u] == R) continue;
                for (int e = head[u]; e != -1; e = edges[e].next) {
                    int v = edges[e].to;
                    if (vis[v] == vis_id) continue;
                    vis[v] = vis_id;
                    dist[v] = dist[u] + 1;
                    queue[back++] = v;
                }
            }
            bestKeep = max(bestKeep, cnt);
            vis_id++;
        }
    } else {
        int R = K / 2;
        for (int u = 1; u <= N; u++) {
            for (int e = head[u]; e != -1; e = edges[e].next) {
                int v = edges[e].to;
                if (u > v) continue; /* process each undirected edge once */

                int front = 0, back = 0;
                queue[back++] = u;
                queue[back++] = v;
                vis[u] = vis_id;
                vis[v] = vis_id;
                dist[u] = 0;
                dist[v] = 0;
                int cnt = 0;

                while (front < back) {
                    int x = queue[front++];
                    cnt++;
                    if (dist[x] == R) continue;
                    for (int ee = head[x]; ee != -1; ee = edges[ee].next) {
                        int y = edges[ee].to;
                        if (vis[y] == vis_id) continue;
                        vis[y] = vis_id;
                        dist[y] = dist[x] + 1;
                        queue[back++] = y;
                    }
                }
                bestKeep = max(bestKeep, cnt);
                vis_id++;
            }
        }
    }

    printf("%d\n", N - bestKeep);

    free(edges);
    free(head);
    free(deg);
    free(queue);
    free(dist);
    free(vis);
    return 0;
}

