public class Main {
    static List<Integer>[] tree;
    static int K, removed;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        K = Integer.parseInt(st.nextToken());

        tree = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) tree[i] = new ArrayList<>();

        for (int i = 0; i < N - 1; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            tree[u].add(v);
            tree[v].add(u);
        }

        removed = 0;
        dfs(1, -1);
        System.out.println(removed);
    }

    static int dfs(int u, int parent) {
        List<Integer> heights = new ArrayList<>();
        for (int v : tree[u]) {
            if (v == parent) continue;
            int h = dfs(v, u);
            heights.add(h);
        }
        Collections.sort(heights);

        while (heights.size() >= 2 && heights.get(heights.size() - 1) + heights.get(heights.size() - 2) > K) {
            removed++;
            heights.remove(heights.size() - 1);
        }

        if (heights.isEmpty()) return 1;
        int maxH = heights.get(heights.size() - 1);
        if (maxH > K) {
            removed++;
            return 1;
        }
        return maxH + 1;
    }
}

