import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int N, K;
    static ArrayList<Integer>[] g;
    static int[] dist;
    static int[] q;

    static int bfsFromCenters(boolean[] isCenter) {
        Arrays.fill(dist, -1);
        int head = 0, tail = 0;
        for (int i = 0; i < N; i++) {
            if (isCenter[i]) {
                dist[i] = 0;
                q[tail++] = i;
            }
        }

        int kept = 0;
        int limit = K / 2;

        while (head < tail) {
            int u = q[head++];
            if (dist[u] > limit) continue;
            kept++;
            if (dist[u] == limit) continue;
            for (int v : g[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q[tail++] = v;
                }
            }
        }
        return kept;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        K = fs.nextInt();

        g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();

        int[][] edges = new int[Math.max(0, N - 1)][2];
        for (int i = 0; i < N - 1; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            edges[i][0] = a;
            edges[i][1] = b;
            g[a].add(b);
            g[b].add(a);
        }

        dist = new int[N];
        q = new int[N];

        int bestKeep = 0;

        if (K % 2 == 0) {
            // One center vertex
            for (int c = 0; c < N; c++) {
                boolean[] isCenter = new boolean[N];
                isCenter[c] = true;
                bestKeep = Math.max(bestKeep, bfsFromCenters(isCenter));
            }
        } else {
            // Two center vertices: an edge
            for (int[] e : edges) {
                boolean[] isCenter = new boolean[N];
                isCenter[e[0]] = true;
                isCenter[e[1]] = true;
                bestKeep = Math.max(bestKeep, bfsFromCenters(isCenter));
            }
        }

        System.out.println(N - bestKeep);
    }
}
